# SPDX-FileCopyrightText: Copyright contributors to the vLLM projectimport itertoolsfrom abc import abstractmethodimport torchfrom torch.nn.parameter import Parameter, UninitializedParameterfrom vllm.config import VllmConfigimport vllm.envs as envsfrom vllm.distributed import (    divide,    get_tensor_model_parallel_rank,    get_tensor_model_parallel_world_size,    split_tensor_along_last_dim,    tensor_model_parallel_all_gather,    tensor_model_parallel_all_reduce,)from vllm.logger import init_loggerfrom vllm.model_executor.custom_op import PluggableLayerfrom vllm.model_executor.layers.batch_invariant import (    linear_batch_invariant,)from vllm.model_executor.layers.quantization.base_config import (    QuantizationConfig,    QuantizeMethodBase,)from vllm.model_executor.layers.linear import (    LinearMethodBase,    LinearBase,    UnquantizedLinearMethod,    ReplicatedLinear,    ColumnParallelLinear,    MergedColumnParallelLinear,    QKVParallelLinear,    RowParallelLinear,    WEIGHT_LOADER_V2_SUPPORTED,    adjust_block_scale_shard,    adjust_marlin_shard,    adjust_bitsandbytes_4bit_shard,    adjust_scalar_to_fused_array)from vllm.model_executor.layers.utils import (    dispatch_unquantized_gemm,)from vllm.model_executor.parameter import (    BasevLLMParameter,    BlockQuantScaleParameter,    ModelWeightParameter,    PackedColumnParameter,    PackedvLLMParameter,    PerTensorScaleParameter,    RowvLLMParameter,)from vllm.model_executor.utils import set_weight_attrsfrom vllm.platforms import current_platformimport loggingerrorlogger = logging.getLogger(__name__)logger = logging.getLogger("vllm")# 支持非对称的ColumnParallelLinearAsymmetric类 继承ColumnParallelLinear# 修改1：需要从上层获取is_qkv_type num_heads num_kv_heads head_size# 修改2：需要知道整体切分为多少份，当前卡切分为多少份class ColumnParallelLinearAsymmetric(ColumnParallelLinear):    def __init__(            self,            input_size: int,            output_size: int,            bias: bool = True,            gather_output: bool = False,            skip_bias_add: bool = False,            params_dtype: torch.dtype | None = None,            quant_config: QuantizationConfig | None = None,            prefix: str = "",            *,            return_bias: bool = True,            disable_tp: bool = False,            is_qkv_type: bool = False,            num_heads: int = 0,            num_kv_heads: int = 0,            head_size: int = 0,            tp_asymmetric_shardings: list = None,  # 非对称新增    ):        # Divide the weight matrix along the last dimension.        self.tp_rank = get_tensor_model_parallel_rank() if not disable_tp else 0        self.tp_size = get_tensor_model_parallel_world_size() if not disable_tp else 1        self.input_size_per_partition = input_size        # tp_asymmetric_shardings = [1,1,2] if self.tp_size == 3 else [1,1,1,1]        self.tp_asymmetric_shardings = tp_asymmetric_shardings        world_split_size = sum(self.tp_asymmetric_shardings)  # 4        tp_rank = get_tensor_model_parallel_rank()  # 0 1 2        split_size = self.tp_asymmetric_shardings[self.tp_rank]  # 1 1 2        # end        self.output_size_per_partition = divide(output_size, world_split_size) * split_size        self.output_partition_sizes = [self.output_size_per_partition]        # If QKV or MergedColumn, use output size of each partition.        if hasattr(self, "output_sizes"):            if not is_qkv_type:                self.output_partition_sizes = []                for output_size in self.output_sizes:                    self.output_partition_sizes.append(                        divide(output_size, world_split_size) * split_size                    )            else:                self.output_partition_sizes = [                    num_heads * head_size,                    num_kv_heads * head_size,                    num_kv_heads * head_size                ]        super(ColumnParallelLinear, self).__init__(            input_size,            output_size,            bias,            skip_bias_add,  # ← 加这个            params_dtype,            quant_config,            prefix,            return_bias=return_bias,            disable_tp=disable_tp,        )        self._maybe_allow_fp8_block_shape_mismatch()        self.gather_output = gather_output        self.quant_method.create_weights(            layer=self,            input_size_per_partition=self.input_size_per_partition,            output_partition_sizes=self.output_partition_sizes,            input_size=self.input_size,            output_size=self.output_size,            params_dtype=self.params_dtype,            weight_loader=(                self.weight_loader_v2                if self.quant_method.__class__.__name__ in WEIGHT_LOADER_V2_SUPPORTED                else self.weight_loader            ),        )        if bias:            self.bias = Parameter(                torch.empty(self.output_size_per_partition, dtype=params_dtype)            )            set_weight_attrs(                self.bias,                {                    "output_dim": 0,                    "weight_loader": self.weight_loader,                },            )        else:            self.register_parameter("bias", None)        self.update_param_tp_status()    def weight_loader(self, param: Parameter, loaded_weight: torch.Tensor):        """Asymmetric TP-aware weight_loader for ColumnParallelLinear.        When asymmetric TP is active (tp_asymmetric_shardings has non-uniform values),        uses cumulative offsets for calculating start_idx. Otherwise falls back to        the original symmetric TP logic.        """        output_dim = getattr(param, "output_dim", None)        is_sharded_weight = getattr(param, "is_sharded_weight", False)        use_bitsandbytes_4bit = getattr(param, "use_bitsandbytes_4bit", False)        is_sharded_weight = is_sharded_weight or use_bitsandbytes_4bit        # Check if asymmetric TP is active for this layer        # Must check if shardings are NON-UNIFORM (not just current rank's shard size)        # e.g., [1,1,2] is non-uniform (sum=4, len=3, each=1.33), [1,1,1] is uniform        is_asymmetric_active = False        if self.tp_asymmetric_shardings is not None and len(self.tp_asymmetric_shardings) > 1:            # Check if shardings are non-uniform (not all equal to 1)            is_asymmetric_active = any(s != self.tp_asymmetric_shardings[0] for s in self.tp_asymmetric_shardings)        # Special case for GGUF        is_gguf_weight = getattr(param, "is_gguf_weight", False)        is_gguf_weight_type = getattr(param, "is_gguf_weight_type", False)        if is_gguf_weight_type:            param.weight_type = loaded_weight.item()        # Materialize GGUF UninitializedParameter        if is_gguf_weight and isinstance(param, UninitializedParameter):            final_shape = list(loaded_weight.shape)            if output_dim is not None:                assert final_shape[output_dim] % self.tp_size == 0                final_shape[output_dim] = final_shape[output_dim] // self.tp_size            param.materialize(final_shape, dtype=loaded_weight.dtype)        param_data = param.data        if output_dim is not None and not is_sharded_weight:            shard_size = param_data.shape[output_dim]            if is_asymmetric_active:                # Asymmetric TP: use cumulative offsets                # split_size = 本rank的分片大小 (e.g., [1,1,2] 中 rank2 的 split_size=2)                split_size = self.tp_asymmetric_shardings[self.tp_rank]                start_idx = sum(self.tp_asymmetric_shardings[:self.tp_rank]) * (shard_size // split_size)            else:                # Original symmetric TP logic                start_idx = self.tp_rank * shard_size            loaded_weight = loaded_weight.narrow(output_dim, start_idx, shard_size)        # Special case for loading scales off disk        if len(loaded_weight.shape) == 0:            loaded_weight = loaded_weight.reshape(1)        assert param_data.shape == loaded_weight.shape        param_data.copy_(loaded_weight)# 支持非对称的QKVParallelLinearAsymmetric类 继承ColumnParallelLinearAsymmetricclass QKVParallelLinearAsymmetric(ColumnParallelLinearAsymmetric):    def __init__(            self,            hidden_size: int,            head_size: int,            total_num_heads: int,            total_num_kv_heads: int | None = None,            bias: bool = True,            skip_bias_add: bool = False,            params_dtype: torch.dtype | None = None,            quant_config: QuantizationConfig | None = None,            prefix: str = "",            *,            return_bias: bool = True,            disable_tp: bool = False,            v_head_size: int | None = None,            tp_asymmetric_shardings: list = None,  # 非对称增加参数下发    ):        self.hidden_size = hidden_size        self.head_size = head_size        self.v_head_size = v_head_size if v_head_size is not None else head_size        self.total_num_heads = total_num_heads        if total_num_kv_heads is None:            total_num_kv_heads = total_num_heads        self.total_num_kv_heads = total_num_kv_heads        # Divide the weight matrix along the last dimension.        tp_size = get_tensor_model_parallel_world_size() if not disable_tp else 1        # 非对称修改        # tp_asymmetric_shardings = [1,1,2] if tp_size == 3 else [1,1,1,1]        self.tp_asymmetric_shardings = tp_asymmetric_shardings        world_split_size = sum(self.tp_asymmetric_shardings)  # TODO: 判断总切分size可以整除head数        split_size = self.tp_asymmetric_shardings[get_tensor_model_parallel_rank()]        self.num_heads = divide(self.total_num_heads, world_split_size) * split_size        # end        if world_split_size >= self.total_num_kv_heads:  # 默认world_split_size和total_num_kv_heads是倍数关系            if (split_size % divide(world_split_size, self.total_num_kv_heads) and                    divide(world_split_size, self.total_num_kv_heads) % split_size):                # TODO: 配置里判断这种情况, 或者之后做适配                pass            elif split_size * self.total_num_kv_heads // world_split_size:                self.num_kv_heads = divide(self.total_num_kv_heads * split_size, world_split_size)                self.num_kv_head_replicas = 1            else:                self.num_kv_heads = 1                self.num_kv_head_replicas = divide(world_split_size, self.total_num_kv_heads * split_size)        else:            self.num_kv_heads = divide(self.total_num_kv_heads, world_split_size) * split_size            self.num_kv_head_replicas = 1        input_size = self.hidden_size        output_size = (                              self.total_num_heads + 2 * self.total_num_kv_heads                      ) * self.head_size        self.output_sizes = [            self.total_num_heads * self.head_size,  # q_proj            self.total_num_kv_heads * self.head_size,  # k_proj            self.total_num_kv_heads * self.head_size,  # v_proj        ]        # end        super().__init__(            input_size=input_size,            output_size=output_size,            bias=bias,            gather_output=False,            skip_bias_add=skip_bias_add,            params_dtype=params_dtype,            quant_config=quant_config,            prefix=prefix,            return_bias=return_bias,            disable_tp=disable_tp,            is_qkv_type=True,            num_heads=self.num_heads,            num_kv_heads=self.num_kv_heads,            head_size=self.head_size,            tp_asymmetric_shardings=self.tp_asymmetric_shardings,        )    def validate_shard_id(self, loaded_shard_id: str | None):        if loaded_shard_id is None:            return        if isinstance(loaded_shard_id, str):            if loaded_shard_id not in ["q", "k", "v"]:                raise ValueError(                    "Shard id for QKVParallelLinear should be 'q', 'k', or 'v', "                    f"got shard id {loaded_shard_id}."                )            return        raise ValueError("This line should not be reached")    def _get_shard_offset_mapping(self, loaded_shard_id: str):        shard_offset_mapping = {            "q": 0,            "k": self.num_heads * self.head_size,            "v": (self.num_heads + self.num_kv_heads) * self.head_size,            "total": (self.num_heads + 2 * self.num_kv_heads) * self.head_size        }        return shard_offset_mapping.get(loaded_shard_id)    def _get_shard_size_mapping(self, loaded_shard_id: str):        shard_size_mapping = {            "q": self.num_heads * self.head_size,            "k": self.num_kv_heads * self.head_size,            "v": self.num_kv_heads * self.head_size,        }        return shard_size_mapping.get(loaded_shard_id)    def _load_fused_module_from_checkpoint(            self, param: BasevLLMParameter, loaded_weight: torch.Tensor    ):        """        Handle special case for models where QKV layers are already        fused on disk. In this case, we have no shard id. This function        determines the shard id by splitting these layers and then calls        the weight loader using the shard id.        An example of a model with these fused layers:        https://huggingface.co/microsoft/Phi-3-mini-4k-instruct        """        shard_offsets = [            # (shard_id, shard_offset, shard_size)            ("q", 0, self.total_num_heads * self.head_size),            (                "k",                self.total_num_heads * self.head_size,                self.total_num_kv_heads * self.head_size,            ),            (                "v",                (self.total_num_heads + self.total_num_kv_heads) * self.head_size,                self.total_num_kv_heads * self.head_size,            ),        ]        for shard_id, shard_offset, shard_size in shard_offsets:            # Special case for Quantization.            # If quantized, we need to adjust the offset and size to account            # for the packing.            if isinstance(param, BlockQuantScaleParameter):                weight_block_size = getattr(self, "weight_block_size", None)                shard_size, shard_offset = adjust_block_scale_shard(                    weight_block_size, shard_size, shard_offset                )            elif (                    isinstance(param, (PackedColumnParameter, PackedvLLMParameter))                    and param.packed_dim == param.output_dim            ):                shard_size, shard_offset = param.adjust_shard_indexes_for_packing(                    shard_size=shard_size, shard_offset=shard_offset                )            loaded_weight_shard = loaded_weight.narrow(                param.output_dim, shard_offset, shard_size            )            self.weight_loader_v2(param, loaded_weight_shard, shard_id)    def weight_loader_v2(            self,            param: BasevLLMParameter,            loaded_weight: torch.Tensor,            loaded_shard_id: str | None = None,    ):        self.validate_shard_id(loaded_shard_id)        if loaded_shard_id is None:  # special case for certain models            if isinstance(param, PerTensorScaleParameter):                # When weights are already fused on disk (e.g. Phi-3's                # qkv_proj), there is only a single scale for the entire                # fused matrix. Fill all slots (q, k, v) with this scale                # to ensure that any subsequent reduction (like .max())                # works correctly while preserving the parameter shape.                for idx in range(param.data.shape[0]):                    param.load_qkv_weight(                        loaded_weight=loaded_weight, shard_id=idx, tp_rank=self.tp_rank                    )                return            elif type(param) in (RowvLLMParameter, BasevLLMParameter):                param.load_qkv_weight(loaded_weight=loaded_weight, tp_rank=self.tp_rank)                return            # TODO: @dsikka - move to parameter.py            self._load_fused_module_from_checkpoint(param, loaded_weight)            return        assert loaded_shard_id in ["q", "k", "v"]        shard_offset = self._get_shard_offset_mapping(loaded_shard_id)        shard_size = self._get_shard_size_mapping(loaded_shard_id)        if isinstance(param, BlockQuantScaleParameter):            weight_block_size = getattr(self, "weight_block_size", None)            shard_size, shard_offset = adjust_block_scale_shard(                weight_block_size, shard_size, shard_offset            )        param.load_qkv_weight(            loaded_weight=loaded_weight,            num_heads=self.num_kv_head_replicas,            shard_id=loaded_shard_id,            shard_offset=shard_offset,            shard_size=shard_size,            tp_rank=self.tp_rank,        )    def weight_loader(            self,            param: Parameter,            loaded_weight: torch.Tensor,            loaded_shard_id: str | None = None,    ):        self.validate_shard_id(loaded_shard_id)        # Special case for GGUF        # initialize GGUF param after we know the quantize type        is_gguf_weight = getattr(param, "is_gguf_weight", False)        is_gguf_weight_type = getattr(param, "is_gguf_weight_type", False)        if is_gguf_weight_type:            idx_map = {"q": 0, "k": 1, "v": 2}            if loaded_shard_id is not None:                param.data[idx_map[loaded_shard_id]].copy_(loaded_weight)                param.shard_weight_type[loaded_shard_id] = loaded_weight.item()            else:                param.shard_weight_type = {k: loaded_weight.item() for k in idx_map}            return        if is_gguf_weight:            output_dim = getattr(param, "output_dim", None)            shard_size = loaded_weight.size(output_dim) // self.tp_size            start_idx = self.tp_rank * shard_size            if loaded_shard_id is not None:                loaded_weight = loaded_weight.narrow(output_dim, start_idx, shard_size)                param.shard_id.append(loaded_shard_id)                param.shard_id_map[loaded_shard_id] = len(param.data_container)                param.data_container.append(loaded_weight)                return        param_data = param.data        output_dim = getattr(param, "output_dim", None)        # Special case for per-tensor scales in fused case.        needs_scalar_to_array = getattr(param, "needs_scalar_to_array", False)        if loaded_shard_id is None:            # Loaded weight is already fused on disk (qkv).            # (e.g., Phi-3's qkv_proj).            if output_dim is None:                if needs_scalar_to_array:                    param_data, loaded_weight = adjust_scalar_to_fused_array(                        param_data, loaded_weight, 0                    )                assert param_data.shape == loaded_weight.shape                param_data.copy_(loaded_weight)                return            shard_offsets = [                # (shard_id, shard_offset, shard_size)                ("q", 0, self.total_num_heads * self.head_size),                (                    "k",                    self.total_num_heads * self.head_size,                    self.total_num_kv_heads * self.head_size,                ),                (                    "v",                    (self.total_num_heads + self.total_num_kv_heads) * self.head_size,                    self.total_num_kv_heads * self.head_size,                ),            ]            use_bitsandbytes_4bit = getattr(param, "use_bitsandbytes_4bit", False)            packed_dim = getattr(param, "packed_dim", None)            for shard_id, shard_offset, shard_size in shard_offsets:                # Special case for Quantized Weights.                # If quantized, we need to adjust the offset and size to account                # for the packing.                # Add check to adjust the size/offset for FP8 block scales                if isinstance(param, BlockQuantScaleParameter):                    weight_block_size = getattr(self, "weight_block_size", None)                    shard_size, shard_offset = adjust_block_scale_shard(                        weight_block_size, shard_size, shard_offset                    )                if packed_dim == output_dim:                    shard_size = round(shard_size // param.packed_factor)                    shard_offset = round(shard_offset // param.packed_factor)                    # Special case for Marlin.                    shard_size, shard_offset = adjust_marlin_shard(                        param, shard_size, shard_offset                    )                if use_bitsandbytes_4bit:                    orig_qkv_offsets = {                        "q": (0, self.total_num_heads * self.head_size),                        "k": (                            self.total_num_heads * self.head_size,                            self.total_num_kv_heads * self.head_size,                        ),                        "v": (                            (self.total_num_heads + self.total_num_kv_heads)                            * self.head_size,                            self.total_num_kv_heads * self.head_size,                        ),                        "total": (                            (self.total_num_heads + 2 * self.total_num_kv_heads) *                            self.head_size,                            0,                        ),                    }                    shard_size, shard_offset = adjust_bitsandbytes_4bit_shard(                        param, orig_qkv_offsets, shard_id                    )                loaded_weight_shard = loaded_weight.narrow(                    output_dim, shard_offset, shard_size                )                self.weight_loader(param, loaded_weight_shard, shard_id)            return        assert loaded_shard_id in ["q", "k", "v"]        # If output dim is defined, use the default loading process.        if output_dim is not None:            if loaded_shard_id == "q":                shard_offset = 0                shard_size = self.num_heads * self.head_size            elif loaded_shard_id == "k":                shard_offset = self.num_heads * self.head_size                shard_size = self.num_kv_heads * self.head_size            elif loaded_shard_id == "v":                shard_offset = (self.num_heads + self.num_kv_heads) * self.head_size                shard_size = self.num_kv_heads * self.head_size            if isinstance(param, BlockQuantScaleParameter):                weight_block_size = getattr(self, "weight_block_size", None)                shard_size, shard_offset = adjust_block_scale_shard(                    weight_block_size, shard_size, shard_offset                )            # Special case for Quantized Weights.            # If quantized, we need to adjust the offset and size to account            # for the packing.            packed_dim = getattr(param, "packed_dim", None)            if packed_dim == output_dim:                shard_size = round(shard_size // param.packed_factor)                shard_offset = round(shard_offset // param.packed_factor)                # Special case for Marlin.                shard_size, shard_offset = adjust_marlin_shard(                    param, shard_size, shard_offset                )            use_bitsandbytes_4bit = getattr(param, "use_bitsandbytes_4bit", False)            is_sharded_weight = getattr(param, "is_sharded_weight", False)            # bitsandbytes loads the weights of the specific portion            # no need to narrow            is_sharded_weight = is_sharded_weight or use_bitsandbytes_4bit            if use_bitsandbytes_4bit:                orig_qkv_offsets = {                    "q": (0, self.num_heads * self.head_size),                    "k": (                        self.num_heads * self.head_size,                        self.num_kv_heads * self.head_size,                    ),                    "v": (                        (self.num_heads + self.num_kv_heads) * self.head_size,                        self.num_kv_heads * self.head_size,                    ),                    "total": (                        (self.num_heads + 2 * self.num_kv_heads) * self.head_size,                        0,                    ),                }                shard_size, shard_offset = adjust_bitsandbytes_4bit_shard(                    param, orig_qkv_offsets, loaded_shard_id                )            param_data = param_data.narrow(output_dim, shard_offset, shard_size)            # tp_asymmetric_shardings = [1,1,2] if self.tp_size == 3 else [1,1,1,1]            world_split_size = sum(self.tp_asymmetric_shardings)            shard_id = sum([self.tp_asymmetric_shardings[i] for i in range(self.tp_rank)])            if loaded_shard_id == "q":                start_idx = (self.total_num_heads * shard_id //                             world_split_size * self.head_size)            else:                start_idx = (self.total_num_kv_heads * shard_id //                             world_split_size * self.head_size)            # end            if not is_sharded_weight:                loaded_weight = loaded_weight.narrow(output_dim, start_idx, shard_size)        # Special case for per-tensor scales in fused case.        elif needs_scalar_to_array:            param_data, loaded_weight = adjust_scalar_to_fused_array(                param_data, loaded_weight, loaded_shard_id            )        else:            ignore_warning = getattr(param, "ignore_warning", False)            if not ignore_warning:                logger.warning(                    "Loading a weight without `output_dim` attribute in "                    "QKVParallelLinear, assume the weight is the same "                    "for all partitions."                )        assert param_data.shape == loaded_weight.shape        param_data.copy_(loaded_weight)class RowParallelLinearAsymmetric(RowParallelLinear):    def __init__(            self,            input_size: int,            output_size: int,            bias: bool = True,            input_is_parallel: bool = True,            skip_bias_add: bool = False,            params_dtype: torch.dtype | None = None,            reduce_results: bool = True,            quant_config: QuantizationConfig | None = None,            prefix: str = "",            *,            return_bias: bool = True,            disable_tp: bool = False,            tp_asymmetric_shardings: list = None,    ):        # Divide the weight matrix along the first dimension.        self.tp_rank = get_tensor_model_parallel_rank() if not disable_tp else 0        self.tp_size = get_tensor_model_parallel_world_size() if not disable_tp else 1        self.tp_asymmetric_shardings = tp_asymmetric_shardings        world_split_size = sum(self.tp_asymmetric_shardings)        split_size = self.tp_asymmetric_shardings[self.tp_rank]        self.input_size_per_partition = divide(input_size, world_split_size) * split_size        # end        self.output_size_per_partition = output_size        self.output_partition_sizes = [output_size]        super(RowParallelLinear, self).__init__(            input_size,            output_size,            bias,            skip_bias_add,            params_dtype,            quant_config,            prefix,            return_bias=return_bias,            disable_tp=disable_tp        )        self.input_is_parallel = input_is_parallel        self.reduce_results = reduce_results        self.quant_method.create_weights(            layer=self,            input_size_per_partition=self.input_size_per_partition,            output_partition_sizes=self.output_partition_sizes,            input_size=self.input_size,            output_size=self.output_size,            params_dtype=self.params_dtype,            weight_loader=(                self.weight_loader_v2                if self.quant_method.__class__.__name__ in WEIGHT_LOADER_V2_SUPPORTED                else self.weight_loader            ),        )        if not reduce_results and (bias and not skip_bias_add):            raise ValueError(                "When not reduce the results, adding bias to the "                "results can lead to incorrect results"            )        if bias:            self.bias = Parameter(torch.empty(self.output_size, dtype=params_dtype))            set_weight_attrs(                self.bias,                {                    "output_dim": 0,                    "weight_loader": self.weight_loader,                },            )        else:            self.register_parameter("bias", None)        self.update_param_tp_status()    def weight_loader(self, param: Parameter, loaded_weight: torch.Tensor):        # ========== 入口日志 - 增强版 ==========        input_dim = getattr(param, 'input_dim', None)        input_dim = getattr(param, "input_dim", None)        use_bitsandbytes_4bit = getattr(param, "use_bitsandbytes_4bit", False)        is_sharded_weight = getattr(param, "is_sharded_weight", False)        # bitsandbytes loads the weights of the specific portion        # no need to narrow        is_sharded_weight = is_sharded_weight or use_bitsandbytes_4bit        # Special case for GGUF        is_gguf_weight = getattr(param, "is_gguf_weight", False)        is_gguf_weight_type = getattr(param, "is_gguf_weight_type", False)        if is_gguf_weight_type:            param.weight_type = loaded_weight.item()        # Materialize GGUF UninitializedParameter        if is_gguf_weight and isinstance(param, UninitializedParameter):            weight_shape = list(loaded_weight.shape)            if input_dim:                weight_shape[input_dim] = weight_shape[input_dim] // self.tp_size            param.materialize(tuple(weight_shape), dtype=loaded_weight.dtype)        param_data = param.data        shard_size = None        split_size = None        start_id = None        start_idx = None        if input_dim is not None and not is_sharded_weight:            shard_size = param_data.shape[input_dim]            split_size = self.tp_asymmetric_shardings[self.tp_rank]            start_id = sum([self.tp_asymmetric_shardings[i] for i in range(self.tp_rank)])            shard_size_per_unit = divide(shard_size, split_size)  # 每个最小分片的大小            start_idx = shard_size_per_unit * start_id            loaded_weight = loaded_weight.narrow(input_dim, start_idx, shard_size)        # Special case for loading scales off disk, which often do not        # have a shape (such as in the case of AutoFP8).        if len(loaded_weight.shape) == 0:            loaded_weight = loaded_weight.reshape(1)        param_data.copy_(loaded_weight)    def forward(self, input_: torch.Tensor) -> torch.Tensor | tuple[torch.Tensor, torch.Tensor]:        """Forward method with detailed logging for debugging all_reduce."""        tp_rank = get_tensor_model_parallel_rank()        tp_size = get_tensor_model_parallel_world_size()        # Manual matmul to capture pre-all_reduce value        weight_t = self.weight.t()        # Call parent forward (includes matmul and all_reduce)        result = super().forward(input_)        return resultclass MergedColumnParallelLinearAsymmetric(ColumnParallelLinearAsymmetric):    """Packed linear layers with column parallelism.    Similar to ColumnParallelLinear, but the weight matrix is concatenated    along the output dimension. When the weight matrix is loaded, the    different partitions are sharded separately.    Args:        input_size: input dimension of the linear layer.        output_sizes: list of output dimensions of the linear layer.        bias: If true, add bias.        gather_output: If true, call all-gather on output and make the output                       available to all GPUs, otherwise, every GPU will have                       its own output.        skip_bias_add: This was added to enable performance optimizations where                       bias can be fused with other element-wise operations. we                       skip adding bias but instead return it.        params_dtype: Data type for the parameters.        quant_config: Quantization configure.        prefix: The name of the layer in the state dict, including all parents                        (e.g. model.layers.0.qkv_proj)        return_bias: If true, return bias together with outputs in forward pass.        disable_tp: If true, all weights matrix won't be sharded, this layer                    will be treated as a "Replicated" MergedLinear.    """    def __init__(            self,            input_size: int,            output_sizes: list[int],            bias: bool = True,            gather_output: bool = False,            skip_bias_add: bool = False,            params_dtype: torch.dtype | None = None,            quant_config: QuantizationConfig | None = None,            prefix: str = "",            *,            return_bias: bool = True,            disable_tp: bool = False,            tp_asymmetric_shardings: list = None,    ):        self.output_sizes = output_sizes        self.tp_size = get_tensor_model_parallel_world_size() if not disable_tp else 1        self.tp_rank = get_tensor_model_parallel_rank() if not disable_tp else 0        self.tp_asymmetric_shardings = tp_asymmetric_shardings        # assert all(output_size % self.tp_size == 0 for output_size in output_sizes)        super().__init__(            input_size=input_size,            output_size=sum(output_sizes),            bias=bias,            gather_output=gather_output,            skip_bias_add=skip_bias_add,            params_dtype=params_dtype,            quant_config=quant_config,            prefix=prefix,            return_bias=return_bias,            disable_tp=disable_tp,            tp_asymmetric_shardings=tp_asymmetric_shardings,        )    def validate_shard_id(self, loaded_shard_id: int | tuple[int, ...] | None):        if loaded_shard_id is None:            return        if isinstance(loaded_shard_id, tuple):            for idx in loaded_shard_id:                if not (0 <= idx < len(self.output_sizes)):                    raise ValueError(                        f"Shard id index {idx} should be between 0 and "                        f"{len(self.output_sizes) - 1}. Got shard id {loaded_shard_id}."                    )            if len(loaded_shard_id) > 1 and any(                    b - a != 1 for a, b in zip(loaded_shard_id[:-1], loaded_shard_id[1:])            ):                raise ValueError(                    "Shard id with multiple indices should be consecutive. "                    f"Got shard id {loaded_shard_id}."                )            return        elif isinstance(loaded_shard_id, int):            if loaded_shard_id < 0 or loaded_shard_id >= len(self.output_sizes):                raise ValueError(                    f"Shard id should be between 0 and {len(self.output_sizes) - 1}. "                    f"Got shard id {loaded_shard_id}."                )            return        raise ValueError("This line should not be reached")    def weight_loader(            self,            param: Parameter,            loaded_weight: torch.Tensor,            loaded_shard_id: tuple[int, ...] | int | None = None,    ):        self.validate_shard_id(loaded_shard_id)        # Special case for GGUF        # initialize GGUF param after we know the quantize type        is_gguf_weight = getattr(param, "is_gguf_weight", False)        is_gguf_weight_type = getattr(param, "is_gguf_weight_type", False)        if isinstance(loaded_shard_id, tuple) and (                is_gguf_weight or is_gguf_weight_type        ):            raise NotImplementedError(                "Shard id with multiple indices is not supported for GGUF."            )        if is_gguf_weight_type:            if loaded_shard_id is not None:                param.data[loaded_shard_id].copy_(loaded_weight)                param.shard_weight_type[loaded_shard_id] = loaded_weight.item()            else:                param.shard_weight_type = {                    i: loaded_weight.item() for i, _ in enumerate(self.output_sizes)                }            return        if is_gguf_weight:            output_dim = getattr(param, "output_dim", None)            shard_size = loaded_weight.size(output_dim) // self.tp_size            start_idx = self.tp_rank * shard_size            if loaded_shard_id is not None:                loaded_weight = loaded_weight.narrow(output_dim, start_idx, shard_size)                param.shard_id.append(loaded_shard_id)                param.shard_id_map[loaded_shard_id] = len(param.data_container)                param.data_container.append(loaded_weight)            return        param_data = param.data        output_dim = getattr(param, "output_dim", None)        # Special case for per-tensor scale to load scalar into fused array.        needs_scalar_to_array = getattr(param, "needs_scalar_to_array", False)        if loaded_shard_id is None or isinstance(loaded_shard_id, tuple):            # Loaded weight is already fused on disk (mlp).            # (e.g., Phi-3's gate_up_proj).            if output_dim is None:                if needs_scalar_to_array:                    param_data, loaded_weight = adjust_scalar_to_fused_array(                        param_data, loaded_weight, 0                    )                assert param_data.shape == loaded_weight.shape                param_data.copy_(loaded_weight)                return            output_sizes = (                self.output_sizes[loaded_shard_id[0]: loaded_shard_id[-1] + 1]                if loaded_shard_id is not None                else self.output_sizes            )            current_shard_offset = 0            use_bitsandbytes_4bit = getattr(param, "use_bitsandbytes_4bit", False)            if (                    use_bitsandbytes_4bit                    and isinstance(loaded_shard_id, tuple)                    and self.tp_size > 1            ):                raise NotImplementedError(                    "Shard id with multiple indices is not supported "                    "for BNB quantization with TP yet."                )            shard_offsets: list[tuple[int, int, int]] = []            for i, output_size in enumerate(output_sizes):                shard_offsets.append((i, current_shard_offset, output_size))                current_shard_offset += output_size            packed_dim = getattr(param, "packed_dim", None)            for shard_id, shard_offset, shard_size in shard_offsets:                # Special case for Quantization.                # If quantized, we need to adjust the offset and size to account                # for the packing.                # Add check to adjust the size/offset for FP8 block scales                if isinstance(param, BlockQuantScaleParameter):                    weight_block_size = getattr(self, "weight_block_size", None)                    shard_size, shard_offset = adjust_block_scale_shard(                        weight_block_size, shard_size, shard_offset                    )                if packed_dim == output_dim:                    shard_size = shard_size // param.packed_factor                    shard_offset = shard_offset // param.packed_factor                    # Special case for Marlin.                    shard_size, shard_offset = adjust_marlin_shard(                        param, shard_size, shard_offset                    )                if use_bitsandbytes_4bit:                    index = list(itertools.accumulate([0] + self.output_sizes))                    orig_offsets = {                        str(i): (index[i], size)                        for i, size in enumerate(self.output_sizes)                    }                    orig_offsets["total"] = (self.output_size, 0)                    shard_size, shard_offset = adjust_bitsandbytes_4bit_shard(                        param, orig_offsets, str(shard_id)                    )                loaded_weight_shard = loaded_weight.narrow(                    output_dim, shard_offset, shard_size                )                self.weight_loader(param, loaded_weight_shard, shard_id)            return        assert loaded_shard_id < len(self.output_sizes)        if output_dim is not None:            # ========== 非对称分片配置 ==========            split_size = self.tp_asymmetric_shardings[self.tp_rank]            world_split_size = sum(self.tp_asymmetric_shardings)  # 4            # 子权重的原始总行数（gate 和 up 相同）            full_subweight_size = self.output_sizes[loaded_shard_id]  # 12288            base = full_subweight_size // world_split_size  # 3072,3072,6144 2,2,4            # 1. 本 rank 在该子权重中分配的行数            shard_size = split_size * base  # 3072,3072,6144 2,2,4            # 2. 本 rank 在子权重中的起始行（前面所有 rank 的累积）            start_idx = sum(self.tp_asymmetric_shardings[:self.tp_rank]) * base            # 3. 本地 param 中的偏移计算            # 使用累积偏移确保每个shard写入正确位置            shard_offset = sum(self.output_partition_sizes[:loaded_shard_id])            # 计算 output_partition_sizes 的累积偏移作为参考            local_cumulative = [0]            for size in self.output_partition_sizes[:-1]:                local_cumulative.append(local_cumulative[-1] + size)            # ========== 量化/打包调整（原样保留） ==========            if isinstance(param, BlockQuantScaleParameter):                weight_block_size = getattr(self, "weight_block_size", None)                shard_size, shard_offset = adjust_block_scale_shard(                    weight_block_size, shard_size, shard_offset                )            packed_dim = getattr(param, "packed_dim", None)            if packed_dim == output_dim:                shard_size = shard_size // param.packed_factor                shard_offset = shard_offset // param.packed_factor                shard_size, shard_offset = adjust_marlin_shard(                    param, shard_size, shard_offset                )            use_bitsandbytes_4bit = getattr(param, "use_bitsandbytes_4bit", False)            is_sharded_weight = getattr(param, "is_sharded_weight", False)            is_sharded_weight = is_sharded_weight or use_bitsandbytes_4bit            if use_bitsandbytes_4bit:                index = list(itertools.accumulate([0] + self.output_sizes))                orig_offsets = {                    str(i): (index[i], size) for i, size in enumerate(self.output_sizes)                }                orig_offsets["total"] = (self.output_size, 0)                shard_size, shard_offset = adjust_bitsandbytes_4bit_shard(                    param, orig_offsets, str(loaded_shard_id)                )            # ========== 执行 narrow ==========            param_data = param_data.narrow(output_dim, shard_offset, shard_size)            if not is_sharded_weight:                loaded_weight = loaded_weight.narrow(output_dim, start_idx, shard_size)        # Special case for per-tensor scales in fused case.        elif needs_scalar_to_array:            param_data, loaded_weight = adjust_scalar_to_fused_array(                param_data, loaded_weight, loaded_shard_id            )        else:            ignore_warning = getattr(param, "ignore_warning", False)        param_data.copy_(loaded_weight)    def _load_fused_module_from_checkpoint(            self,            param: BasevLLMParameter,            loaded_weight: torch.Tensor,            output_sizes: list[int] | None = None,    ):        """        Handle special case for models where MLP layers are already        fused on disk. In this case, we have no shard id. This function        determines the shard id by splitting these layers and then calls        the weight loader using the shard id.        An example of a model with these fused layers:        https://huggingface.co/microsoft/Phi-3-mini-4k-instruct        """        current_shard_offset = 0        shard_offsets: list[tuple[int, int, int]] = []        output_sizes = output_sizes or self.output_sizes        for i, output_size in enumerate(output_sizes):            shard_offsets.append((i, current_shard_offset, output_size))            current_shard_offset += output_size        for shard_id, shard_offset, shard_size in shard_offsets:            # Special case for Quantization.            # If quantized, we need to adjust the offset and size to account            # for the packing.            if (                    isinstance(param, (PackedColumnParameter, PackedvLLMParameter))                    and param.packed_dim == param.output_dim            ):                shard_size, shard_offset = param.adjust_shard_indexes_for_packing(                    shard_size=shard_size, shard_offset=shard_offset                )            loaded_weight_shard = loaded_weight.narrow(                param.output_dim, shard_offset, shard_size            )            self.weight_loader_v2(param, loaded_weight_shard, shard_id)    def weight_loader_v2(            self,            param: BasevLLMParameter,            loaded_weight: torch.Tensor,            loaded_shard_id: tuple[int, ...] | int | None = None,    ):        self.validate_shard_id(loaded_shard_id)        if loaded_shard_id is None or isinstance(loaded_shard_id, tuple):            if isinstance(param, PerTensorScaleParameter):                if isinstance(loaded_shard_id, tuple):                    for idx in loaded_shard_id:                        param.load_merged_column_weight(                            loaded_weight=loaded_weight, shard_id=idx                        )                else:                    # When weights are already fused on disk (e.g. Phi-3's                    # gate_up_proj), there is only a single scale for the                    # entire fused matrix. Fill all slots with this scale                    # to ensure that any subsequent reduction (like .max())                    # works correctly while preserving the parameter shape.                    for idx in range(param.data.shape[0]):                        param.load_merged_column_weight(                            loaded_weight=loaded_weight, shard_id=idx                        )                return            elif type(param) in (RowvLLMParameter, BasevLLMParameter):                param.load_merged_column_weight(loaded_weight=loaded_weight)                return            output_sizes = (                [self.output_sizes[idx] for idx in loaded_shard_id]                if loaded_shard_id                else None            )            if isinstance(param, BlockQuantScaleParameter):                weight_block_size = getattr(self, "weight_block_size", None)                output_sizes = [                    adjust_block_scale_shard(weight_block_size, size, 0)[0]                    for size in (output_sizes or self.output_sizes)                ]            # TODO: @dsikka - move to parameter.py            self._load_fused_module_from_checkpoint(                param, loaded_weight, output_sizes=output_sizes            )            return        assert loaded_shard_id < len(self.output_sizes)        shard_offset = sum(self.output_sizes[:loaded_shard_id])        shard_size = self.output_sizes[loaded_shard_id]        shard_offset //= self.tp_size        shard_size //= self.tp_size        if isinstance(param, BlockQuantScaleParameter):            weight_block_size = getattr(self, "weight_block_size", None)            shard_size, shard_offset = adjust_block_scale_shard(                weight_block_size, shard_size, shard_offset            )        param.load_merged_column_weight(            loaded_weight=loaded_weight,            shard_id=loaded_shard_id,            shard_offset=shard_offset,            shard_size=shard_size,            tp_rank=self.tp_rank,        )